1 | /**
2 |  * Agent API client. All calls go through these typed wrappers.
3 |  * Base URL is read from NEXT_PUBLIC_AGENT_URL (client-side) or
4 |  * AGENT_URL (server actions), falling back to localhost:8003.
5 |  */
6 | import type {
7 |   AuditRow,
8 |   ApproveBody,
9 |   DecideOut,
10 |   ExecuteOut,
11 |   ProposalSet,
12 |   ProxyRoute,
13 | } from "@/types/guardrail";
14 | 
15 | function agentBase(): string {
16 |   // Server-side (Route Handlers / Server Actions) uses the internal Docker URL
17 |   if (typeof window === "undefined") {
18 |     return process.env.AGENT_URL ?? "http://localhost:8003";
19 |   }
20 |   return process.env.NEXT_PUBLIC_AGENT_URL ?? "http://localhost:8003";
21 | }
22 | 
23 | async function apiFetch<T>(path: string, init?: RequestInit): Promise<T> {
24 |   const res = await fetch(`${agentBase()}${path}`, {
25 |     headers: { "Content-Type": "application/json", ...init?.headers },
26 |     ...init,
27 |   });
28 |   if (!res.ok) {
29 |     const text = await res.text().catch(() => res.statusText);
30 |     throw new Error(`Agent API ${path} → ${res.status}: ${text}`);
31 |   }
32 |   return res.json() as Promise<T>;
33 | }
34 | 
35 | /** GET /health */
36 | export function getHealth(): Promise<{ ok: boolean }> {
37 |   return apiFetch("/health");
38 | }
39 | 
40 | /** POST /decide — triggers Decision module, returns verdict + reasons */
41 | export function postDecide(): Promise<DecideOut> {
42 |   return apiFetch<DecideOut>("/decide", { method: "POST" });
43 | }
44 | 
45 | /** POST /propose — Decision + Proposals + persist, returns ProposalSet */
46 | export function postPropose(): Promise<ProposalSet> {
47 |   return apiFetch<ProposalSet>("/propose", { method: "POST" });
48 | }
49 | 
50 | /** GET /proposals — recent proposal sets, newest first */
51 | export function getProposals(): Promise<ProposalSet[]> {
52 |   return apiFetch<ProposalSet[]>("/proposals");
53 | }
54 | 
55 | /** GET /audit — recent execution records */
56 | export function getAudit(): Promise<AuditRow[]> {
57 |   return apiFetch<AuditRow[]>("/audit");
58 | }
59 | 
60 | /** POST /execute — approve + execute the traffic flip */
61 | export function postExecute(body: ApproveBody): Promise<ExecuteOut> {
62 |   return apiFetch<ExecuteOut>("/execute", {
63 |     method: "POST",
64 |     body: JSON.stringify(body),
65 |   });
66 | }
67 | 
68 | /** GET proxy /admin/route — current routing target */
69 | export function getProxyRoute(): Promise<ProxyRoute> {
70 |   const proxyBase =
71 |     typeof window === "undefined"
72 |       ? (process.env.PROXY_ADMIN_URL ?? "http://proxy:8080")
73 |       : (process.env.NEXT_PUBLIC_PROXY_URL ?? "http://localhost:8080");
74 |   return fetch(`${proxyBase}/admin/route`).then((r) => r.json());
75 | }
