1 | /**
2 |  * Supabase real-time log subscription hook.
3 |  *
4 |  * Bootstraps by fetching the most recent rows, then augments with
5 |  * INSERT events pushed over the Realtime channel.  Components stay
6 |  * simple — they just read `{ rows, isLoading, error }`.
7 |  */
8 | "use client";
9 | 
10 | import { useEffect, useRef, useState } from "react";
11 | import { supabase } from "@/lib/supabase";
12 | import type { LogRow } from "@/types/guardrail";
13 | 
14 | const INITIAL_LIMIT = 200;
15 | 
16 | export interface UseLogsOptions {
17 |   /** Filter to a single service (e.g. "stable" | "canary") */
18 |   service?: string;
19 |   /** Max rows to keep in memory (oldest shed first) */
20 |   maxRows?: number;
21 | }
22 | 
23 | export interface UseLogsResult {
24 |   rows: LogRow[];
25 |   isLoading: boolean;
26 |   error: string | null;
27 |   refresh: () => void;
28 | }
29 | 
30 | export function useLogs({
31 |   service,
32 |   maxRows = 500,
33 | }: UseLogsOptions = {}): UseLogsResult {
34 |   const [rows, setRows] = useState<LogRow[]>([]);
35 |   const [isLoading, setIsLoading] = useState(true);
36 |   const [error, setError] = useState<string | null>(null);
37 |   // Stable ref so the realtime callback always has the latest maxRows
38 |   const maxRowsRef = useRef(maxRows);
39 |   maxRowsRef.current = maxRows;
40 | 
41 |   function append(incoming: LogRow[]) {
42 |     setRows((prev) => {
43 |       const merged = [...incoming, ...prev];
44 |       return merged.slice(0, maxRowsRef.current);
45 |     });
46 |   }
47 | 
48 |   async function fetchInitial() {
49 |     setIsLoading(true);
50 |     setError(null);
51 |     try {
52 |       let query = supabase
53 |         .from("logs")
54 |         .select("*")
55 |         .order("timestamp", { ascending: false })
56 |         .limit(INITIAL_LIMIT);
57 | 
58 |       if (service) {
59 |         query = query.eq("service", service);
60 |       }
61 | 
62 |       const { data, error: sbError } = await query;
63 |       if (sbError) throw sbError;
64 |       setRows((data as LogRow[]) ?? []);
65 |     } catch (err) {
66 |       setError(err instanceof Error ? err.message : "Failed to load logs");
67 |     } finally {
68 |       setIsLoading(false);
69 |     }
70 |   }
71 | 
72 |   useEffect(() => {
73 |     void fetchInitial();
74 | 
75 |     // Subscribe to new inserts
76 |     const channel = supabase
77 |       .channel("logs-realtime")
78 |       .on(
79 |         "postgres_changes",
80 |         {
81 |           event: "INSERT",
82 |           schema: "public",
83 |           table: "logs",
84 |           // Server-side filter when a specific service is requested
85 |           ...(service ? { filter: `service=eq.${service}` } : {}),
86 |         },
87 |         (payload) => {
88 |           append([payload.new as LogRow]);
89 |         },
90 |       )
91 |       .subscribe();
92 | 
93 |     return () => {
94 |       void supabase.removeChannel(channel);
95 |     };
96 |     // eslint-disable-next-line react-hooks/exhaustive-deps
97 |   }, [service]);
98 | 
99 |   return { rows, isLoading, error, refresh: fetchInitial };
100 | }
101 |

