1 | /**
2 |  * Agent API query hooks.
3 |  *
4 |  * Reads  → useQuery  (cached, deduplicated, background-refreshable)
5 |  * Writes → useMutation (optimistic-friendly, exposes isPending / error)
6 |  */
7 | import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
8 | import { toast } from "sonner";
9 | import {
10 |   getHealth,
11 |   getProposals,
12 |   getAudit,
13 |   postDecide,
14 |   postPropose,
15 |   postExecute,
16 | } from "@/lib/api";
17 | import { queryKeys } from "./query-keys";
18 | import type { ApproveBody } from "@/types/guardrail";
19 | 
20 | // ── Agent health ──────────────────────────────────────────────────────────────
21 | 
22 | export function useAgentHealth() {
23 |   return useQuery({
24 |     queryKey: queryKeys.health,
25 |     queryFn: getHealth,
26 |     refetchInterval: 15_000, // poll every 15s to surface outages quickly
27 |   });
28 | }
29 | 
30 | // ── Proxy route ───────────────────────────────────────────────────────────────
31 | 
32 | export function useProxyRoute() {
33 |   return useQuery({
34 |     queryKey: queryKeys.proxyRoute,
35 |     queryFn: async () => {
36 |       const proxyUrl =
37 |         process.env.NEXT_PUBLIC_PROXY_URL ?? "http://localhost:8080";
38 |       const res = await fetch(`${proxyUrl}/admin/route`);
39 |       if (!res.ok) throw new Error("Proxy unreachable");
40 |       return res.json() as Promise<{ target: "stable" | "canary" }>;
41 |     },
42 |     refetchInterval: 10_000,
43 |   });
44 | }
45 | 
46 | // ── Proposals (list) ──────────────────────────────────────────────────────────
47 | 
48 | export function useProposals() {
49 |   return useQuery({
50 |     queryKey: queryKeys.proposals,
51 |     queryFn: getProposals,
52 |   });
53 | }
54 | 
55 | // ── Audit trail ───────────────────────────────────────────────────────────────
56 | 
57 | export function useAudit() {
58 |   return useQuery({
59 |     queryKey: queryKeys.audit,
60 |     queryFn: getAudit,
61 |   });
62 | }
63 | 
64 | // ── Decide mutation ───────────────────────────────────────────────────────────
65 | 
66 | export function useDecide() {
67 |   const qc = useQueryClient();
68 |   return useMutation({
69 |     mutationFn: postDecide,
70 |     onSuccess: () => {
71 |       void qc.invalidateQueries({ queryKey: queryKeys.proposals });
72 |     },
73 |     onError: (err) => {
74 |       toast.error(`Decision failed: ${err.message}`);
75 |     },
76 |   });
77 | }
78 | 
79 | // ── Propose mutation ──────────────────────────────────────────────────────────
80 | 
81 | export function usePropose() {
82 |   const qc = useQueryClient();
83 |   return useMutation({
84 |     mutationFn: postPropose,
85 |     onSuccess: () => {
86 |       void qc.invalidateQueries({ queryKey: queryKeys.proposals });
87 |     },
88 |     onError: (err) => {
89 |       toast.error(`Propose failed: ${err.message}`);
90 |     },
91 |   });
92 | }
93 | 
94 | // ── Execute (traffic flip) mutation ───────────────────────────────────────────
95 | 
96 | export function useExecute() {
97 |   const qc = useQueryClient();
98 |   return useMutation({
99 |     mutationFn: (body: ApproveBody) => postExecute(body),
100 |     onSuccess: (data) => {
101 |       toast.success(
102 |         `Traffic flipped to ${data.target}`,
103 |         { description: "Execution recorded in Audit Trail." },
104 |       );
105 |       void qc.invalidateQueries({ queryKey: queryKeys.audit });
106 |       void qc.invalidateQueries({ queryKey: queryKeys.proxyRoute });
107 |       void qc.invalidateQueries({ queryKey: queryKeys.proposals });
108 |     },
109 |     onError: (err) => {
110 |       toast.error(`Execution failed: ${err.message}`);
111 |     },
112 |   });
113 | }
