1 | /**
2 |  * Supabase real-time log subscription hook.
3 |  *
4 |  * Bootstraps by fetching the most recent rows, then augments with
5 |  * INSERT events pushed over the Realtime channel.  Components stay
6 |  * simple — they just read `{ rows, isLoading, error }`.
7 |  */
8 | "use client";
9 | 
10 | import { useEffect, useRef, useState } from "react";
11 | import { getSupabase } from "@/lib/supabase";
12 | import type { LogRow } from "@/types/guardrail";
13 | 
14 | const INITIAL_LIMIT = 200;
15 | 
16 | export interface UseLogsOptions {
17 |   /** Filter to a single service (e.g. "stable" | "canary") */
18 |   service?: string;
19 |   /** Max rows to keep in memory (oldest shed first) */
20 |   maxRows?: number;
21 | }
22 | 
23 | export interface UseLogsResult {
24 |   rows: LogRow[];
25 |   isLoading: boolean;
26 |   error: string | null;
27 |   refresh: () => void;
28 | }
29 | 
30 | export function useLogs({
31 |   service,
32 |   maxRows = 500,
33 | }: UseLogsOptions = {}): UseLogsResult {
34 |   const [rows, setRows] = useState<LogRow[]>([]);
35 |   const [isLoading, setIsLoading] = useState(true);
36 |   const [error, setError] = useState<string | null>(null);
37 |   // Stable ref so the realtime callback always has the latest maxRows
38 |   const maxRowsRef = useRef(maxRows);
39 |   maxRowsRef.current = maxRows;
40 | 
41 |   function append(incoming: LogRow[]) {
42 |     setRows((prev) => {
43 |       const merged = [...incoming, ...prev];
44 |       return merged.slice(0, maxRowsRef.current);
45 |     });
46 |   }
47 | 
48 |   async function fetchInitial() {
49 |     setIsLoading(true);
50 |     setError(null);
51 |     try {
52 |       const sb = getSupabase();
53 |       let query = sb
54 |         .from("logs")
55 |         .select("*")
56 |         .order("timestamp", { ascending: false })
57 |         .limit(INITIAL_LIMIT);
58 | 
59 |       if (service) {
60 |         query = query.eq("service", service);
61 |       }
62 | 
63 |       const { data, error: sbError } = await query;
64 |       if (sbError) throw sbError;
65 |       setRows((data as LogRow[]) ?? []);
66 |     } catch (err) {
67 |       setError(err instanceof Error ? err.message : "Failed to load logs");
68 |     } finally {
69 |       setIsLoading(false);
70 |     }
71 |   }
72 | 
73 |   useEffect(() => {
74 |     void fetchInitial();
75 | 
76 |     // Subscribe to new inserts
77 |     const sb = getSupabase();
78 |     const channel = sb
79 |       .channel("logs-realtime")
80 |       .on(
81 |         "postgres_changes",
82 |         {
83 |           event: "INSERT",
84 |           schema: "public",
85 |           table: "logs",
86 |           ...(service ? { filter: `service=eq.${service}` } : {}),
87 |         },
88 |         (payload) => {
89 |           append([payload.new as LogRow]);
90 |         },
91 |       )
92 |       .subscribe();
93 | 
94 |     return () => {
95 |       void sb.removeChannel(channel);
96 |     };
97 |     // eslint-disable-next-line react-hooks/exhaustive-deps
98 |   }, [service]);
99 | 
100 |   return { rows, isLoading, error, refresh: fetchInitial };
101 | }
