1 | import { ServiceName, isError, makeLogRow } from "@guardrail/contracts";
2 | 
3 | // ── Logging adapter ─────────────────────────────────────────────────────────
4 | // Audit trail writes live here, behind the Proxy interface. Logging never
5 | // blocks proxying: failures are swallowed by design.
6 | 
7 | /** Typed flip event: an admin action recorded in note, never in error_message. */
8 | export function makeFlipRow(target) {
9 |   return makeLogRow({
10 |     service: ServiceName.PROXY_EVENT,
11 |     endpoint: "/admin/route",
12 |     status_code: 200,
13 |     latency_ms: 0,
14 |     note: `traffic flip to ${target}`,
15 |   });
16 | }
17 | 
18 | export function createLogger(client) {
19 |   async function logRow(row) {
20 |     if (!client) return;
21 |     try {
22 |       await client.from("logs").insert(row);
23 |     } catch {
24 |       // never block proxying on logging
25 |     }
26 |   }
27 | 
28 |   async function logFlip(target) {
29 |     await logRow(makeFlipRow(target));
30 |   }
31 | 
32 |   function trafficMiddleware(getTarget) {
33 |     return (req, res, next) => {
34 |       const started = Date.now();
35 |       res.on("finish", () => {
36 |         void logRow(makeLogRow({
37 |           service: ServiceName.PROXY_TRAFFIC(getTarget()),
38 |           endpoint: req.originalUrl,
39 |           status_code: res.statusCode,
40 |           latency_ms: Date.now() - started,
41 |           error_text: isError(res.statusCode) ? `proxy saw ${res.statusCode}` : null,
42 |         }));
43 |       });
44 |       next();
45 |     };
46 |   }
47 | 
48 |   return { logRow, logFlip, trafficMiddleware };
49 | }
